    fun outlines(view:BodyView):List<Outline> = if(view==BodyView.FRONT)front else back
    fun viewFor(muscle:MuscleId):BodyView = if(muscle in BACK_ONLY)BodyView.BACK else BodyView.FRONT
    fun crop(muscle:MuscleId):Rect {
        if(muscle==MuscleId.GLUTES)return Rect(345,660,679,900)
        val paths=outlines(viewFor(muscle)).filter {it.muscle==muscle}.let {if(muscle in MIDLINE)it else it.take(1)}
        if(paths.isEmpty())return Rect(0,0,1024,1536)
        val bounds=RectF()
        paths.forEachIndexed {index,outline->val rect=RectF();PathParser.createPathFromPathData(outline.data)!!.computeBounds(rect,true);if(index==0)bounds.set(rect)else bounds.union(rect)}
        return Rect((bounds.left-12).toInt().coerceAtLeast(0),(bounds.top-12).toInt().coerceAtLeast(0),(bounds.right+12).toInt().coerceAtMost(1024),(bounds.bottom+12).toInt().coerceAtMost(1536))
    }
